import { Component, OnInit, Input, HostListener, ElementRef } from '@angular/core';
import { TokenService } from '../../service/token.service';
import { UserService } from '../../service/user.service';
import { Router } from '@angular/router';

@Component({
	selector: 'cdk-user-menu',
	templateUrl: './user-menu.component.html',
	styleUrls: ['./user-menu.component.scss']
})
export class UserMenuComponent implements OnInit {
	isOpen: boolean = false;

	Hari;

	@Input() currentUser = null;
	@HostListener('document:click', ['$event', '$event.target'])
	onClick(event: MouseEvent, targetElement: HTMLElement) {
		if (!targetElement) {
			return;
		}

		const clickedInside = this.elementRef.nativeElement.contains(targetElement);
		if (!clickedInside) {
			this.isOpen = false;
		}
	}


	constructor(private elementRef: ElementRef, private _tokenService: TokenService, private _userService: UserService,public router: Router) { }


	ngOnInit() {
		const user = this._userService.currentUser();
		if( user ){
      console.log('teste');
      let usuario =  JSON.parse(user);
      let membro = usuario.principal.membro;
      if(membro.nome){
        this.currentUser = membro.nome;
      }else{
        this.currentUser = usuario.name;
      }

		}
	}

	logout() {
		console.log('logout');
		this._tokenService.clear();
		this._userService.clear();
		this.router.navigate(['/login']);
	}

}
